UPDATE lessons SET content = $lsn${"steps": [{"step_type": "concept", "title": "A block you have seen", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "You saw 는 in your first lesson. 저 means I, and 는 marks the topic.", "example": {"sentence": "저는 빵을 먹어요.", "translation": "I eat bread.", "tts": true, "words": [{"parts": [{"text": "저", "meaning": "I", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "빵을", "meaning": "bread (object)", "highlight": false}]}, {"parts": [{"text": "먹어요", "meaning": "eat", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "What is a topic?", "instruction": "", "content": {"character": "turtle", "mood": "happy", "explanation": "민수 and 유미 are names. The topic is who or what we're talking about.", "example": {"sentence": "민수는 빵을 먹어요.", "translation": "Minsu eats bread.", "tts": true, "words": [{"parts": [{"text": "민수", "meaning": "Minsu", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "빵을", "meaning": "bread (object)", "highlight": false}]}, {"parts": [{"text": "먹어요", "meaning": "eat", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "Yumi eats bread.", "sentence": "유미 [ ? ] 빵을 먹어요.", "options": ["을", "는"], "answer": "는", "feedback": {"correct": "Yes! 유미 is the topic, so it takes 는.", "incorrect": "을 goes on the thing you eat. 유미 is who we're talking about, so use 는."}}]}}, {"step_type": "concept", "title": "Say who you are", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "유미예요 means am Yumi. Keep it whole for now, and we'll open it next lesson.", "example": {"sentence": "저는 유미예요.", "translation": "I am Yumi.", "tts": true, "words": [{"parts": [{"text": "저", "meaning": "I", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "유미예요", "meaning": "am Yumi", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "Same block, new name", "instruction": "", "content": {"character": "turtle", "mood": "happy", "explanation": "저, 민수 and 유미 all end in a vowel. After a vowel, the block is 는.", "example": {"sentence": "저는 민수예요.", "translation": "I am Minsu.", "tts": true, "words": [{"parts": [{"text": "저", "meaning": "I", "highlight": false}, {"text": "는", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "민수예요", "meaning": "am Minsu", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "I am Minsu.", "sentence": "저 [ ? ] 민수예요.", "options": ["는", "은"], "answer": "는", "feedback": {"correct": "Right! 저 ends in a vowel, so it takes 는.", "incorrect": "저 ends in a vowel. After a vowel, use 는."}}]}}, {"step_type": "concept", "title": "Sometimes it is 은", "instruction": "", "content": {"character": "turtle", "mood": "thinking", "explanation": "제 means my, and 이름 means name. 이름 ends in a consonant, so the block is 은, not 는.", "example": {"sentence": "제 이름은 유미예요.", "translation": "My name is Yumi.", "tts": true, "words": [{"parts": [{"text": "제", "meaning": "my", "highlight": false}]}, {"parts": [{"text": "이름", "meaning": "name", "highlight": false}, {"text": "은", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "유미예요", "meaning": "is Yumi", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "concept", "title": "How to choose", "instruction": "", "content": {"character": "turtle", "mood": "talking", "explanation": "After a consonant, use 은, like 학생, student. After a vowel, use 는.", "example": {"sentence": "학생은 빵을 먹어요.", "translation": "The student eats bread.", "tts": true, "words": [{"parts": [{"text": "학생", "meaning": "student", "highlight": false}, {"text": "은", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "빵을", "meaning": "bread (object)", "highlight": false}]}, {"parts": [{"text": "먹어요", "meaning": "eat", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "practice", "title": "Quick check", "instruction": "No score here. Just try it.", "content": {"graded": false, "character": "turtle", "exercises": [{"type": "fill_blank", "instruction": "My name is Minsu.", "sentence": "제 이름 [ ? ] 민수예요.", "options": ["는", "은"], "answer": "은", "feedback": {"correct": "Great! 이름 ends in a consonant, so it takes 은.", "incorrect": "이름 ends in a consonant. After a consonant, use 은."}}]}}, {"step_type": "completion", "title": "은/는 Learned!", "instruction": "Next, practice it with the rabbit.", "content": {"text": "은 and 는 mark the topic: who or what we're talking about.\nConsonant → 은 (이름은). Vowel → 는 (저는).", "highlights": ["은", "는"]}}]}$lsn$::jsonb
WHERE lesson_id = 'u1-l1-learn';
UPDATE lessons SET content = $lsn${"steps": [{"step_type": "concept", "title": "Quick recap", "instruction": "", "content": {"character": "rabbit", "mood": "happy", "explanation": "After a consonant, use 은. After a vowel, use 는.", "example": {"sentence": "이름은 유미예요.", "translation": "My name is Yumi.", "tts": true, "words": [{"parts": [{"text": "이름", "meaning": "name", "highlight": false}, {"text": "은", "meaning": "topic", "highlight": true}]}, {"parts": [{"text": "유미예요", "meaning": "is Yumi", "highlight": false}]}]}, "tap_to_assemble": true}}, {"step_type": "intro", "title": "Vocabulary: Meeting People", "instruction": "Tap and listen. You'll use all of these today.", "content": {"explanation": {"title": "Words for today"}, "sentences": [{"korean": "안녕하세요", "english": "Hello", "tts": true, "chunks": [{"display": "안녕하세요", "tokens": [{"text": "안녕하세요", "meaning": "hello"}]}]}, {"korean": "저", "english": "I", "tts": true, "chunks": [{"display": "저", "tokens": [{"text": "저", "meaning": "i"}]}]}, {"korean": "제", "english": "My", "tts": true, "chunks": [{"display": "제", "tokens": [{"text": "제", "meaning": "my"}]}]}, {"korean": "이름", "english": "Name", "tts": true, "chunks": [{"display": "이름", "tokens": [{"text": "이름", "meaning": "name"}]}]}, {"korean": "학생", "english": "Student", "tts": true, "chunks": [{"display": "학생", "tokens": [{"text": "학생", "meaning": "student"}]}]}, {"korean": "선생님", "english": "Teacher", "tts": true, "chunks": [{"display": "선생님", "tokens": [{"text": "선생님", "meaning": "teacher"}]}]}, {"korean": "빵", "english": "Bread", "tts": true, "chunks": [{"display": "빵", "tokens": [{"text": "빵", "meaning": "bread"}]}]}, {"korean": "먹어요", "english": "Eat", "tts": true, "chunks": [{"display": "먹어요", "tokens": [{"text": "먹어요", "meaning": "eat"}]}]}, {"korean": "반가워요", "english": "Nice to meet you", "tts": true, "chunks": [{"display": "반가워요", "tokens": [{"text": "반가워요", "meaning": "nice to meet you"}]}]}]}}, {"step_type": "practice", "title": "Round 1: Spot the topic", "instruction": "은 and 는 mark who or what we're talking about.", "content": {"exercises": [{"type": "fill_blank", "instruction": "I eat bread.", "sentence": "[ ? ] 빵을 먹어요.", "options": ["저를", "저는"], "answer": "저는", "feedback": {"correct": "Correct! You're the topic, so 저는."}}, {"type": "fill_blank", "instruction": "Minsu eats bread.", "sentence": "[ ? ] 빵을 먹어요.", "options": ["민수는", "민수를"], "answer": "민수는", "feedback": {"correct": "Right! Minsu is the topic, so 민수는."}}, {"type": "fill_blank", "instruction": "My name is Yumi.", "sentence": "제 [ ? ] 유미예요.", "options": ["이름을", "이름은"], "answer": "이름은", "feedback": {"correct": "Great! Your name is the topic, so 이름은."}}, {"type": "fill_blank", "instruction": "Yumi eats bread.", "sentence": "[ ? ] 빵을 먹어요.", "options": ["유미는", "유미를"], "answer": "유미는", "feedback": {"correct": "Perfect! Yumi is the topic, so 유미는."}}, {"type": "fill_blank", "instruction": "The teacher eats bread.", "sentence": "[ ? ] 빵을 먹어요.", "options": ["선생님을", "선생님은"], "answer": "선생님은", "feedback": {"correct": "Correct! The teacher is the topic, so 선생님은."}}]}}, {"step_type": "practice", "title": "Round 2: 은 or 는?", "instruction": "Look at the last sound of the word.", "content": {"exercises": [{"type": "fill_blank", "instruction": "I am Minsu.", "sentence": "저 [ ? ] 민수예요.", "options": ["은", "는"], "answer": "는", "feedback": {"correct": "Correct! 저 ends in a vowel, so it takes 는."}}, {"type": "fill_blank", "instruction": "My name is Yumi.", "sentence": "제 이름 [ ? ] 유미예요.", "options": ["은", "는"], "answer": "은", "feedback": {"correct": "Right! 이름 ends in a consonant, so it takes 은."}}, {"type": "fill_blank", "instruction": "Minsu eats bread.", "sentence": "민수 [ ? ] 빵을 먹어요.", "options": ["는", "은"], "answer": "는", "feedback": {"correct": "Great! 민수 ends in a vowel, so it takes 는."}}, {"type": "fill_blank", "instruction": "The student eats bread.", "sentence": "학생 [ ? ] 빵을 먹어요.", "options": ["는", "은"], "answer": "은", "feedback": {"correct": "Perfect! 학생 ends in a consonant, so it takes 은."}}, {"type": "fill_blank", "instruction": "Yumi eats bread.", "sentence": "유미 [ ? ] 빵을 먹어요.", "options": ["은", "는"], "answer": "는", "feedback": {"correct": "Correct! 유미 ends in a vowel, so it takes 는."}}, {"type": "fill_blank", "instruction": "The teacher eats bread.", "sentence": "선생님 [ ? ] 빵을 먹어요.", "options": ["은", "는"], "answer": "은", "feedback": {"correct": "Right! 선생님 ends in a consonant, so it takes 은."}}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #1", "instruction": "Build the sentence: \"My name is Minsu.\" Split 은/는. 이름 ends in a consonant, so use 은.", "contentObj": {"sentence": "제 이름은 민수예요.", "translation": "My name is Minsu.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["제"], "correct_turtle": ["제"], "turtle_explanation": "Keep '제' as one block — it is not this lesson's focus."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["이름은"], "correct_turtle": ["이름", "은"], "turtle_explanation": "'은' marks the topic. After a vowel use 는, after a consonant use 은."}, {"id": "e3", "isTarget": true, "correct_rabbit": ["민수예요"], "correct_turtle": ["민수예요"], "turtle_explanation": "Keep '민수예요' as one block — it is not this lesson's focus."}], "options": [{"id": "o1", "text": "이름은", "mode": "rabbit"}, {"id": "o2", "text": "는", "mode": "turtle"}, {"id": "o3", "text": "이름는", "mode": "rabbit"}, {"id": "o4", "text": "이름", "mode": "turtle"}, {"id": "o5", "text": "민수예요", "mode": "turtle"}, {"id": "o6", "text": "민수예요", "mode": "rabbit"}, {"id": "o7", "text": "제", "mode": "turtle"}, {"id": "o8", "text": "제", "mode": "rabbit"}, {"id": "o9", "text": "은", "mode": "turtle"}]}}, {"stepType": "agglutinative_quiz", "title": "Sentence Building #2", "instruction": "Build the sentence: \"I am Yumi.\" Split 은/는 from the word.", "contentObj": {"sentence": "저는 유미예요.", "translation": "I am Yumi.", "elements": [{"id": "e1", "isTarget": true, "correct_rabbit": ["저는"], "correct_turtle": ["저", "는"], "turtle_explanation": "'는' marks the topic. After a vowel use 는, after a consonant use 은."}, {"id": "e2", "isTarget": true, "correct_rabbit": ["유미예요"], "correct_turtle": ["유미예요"], "turtle_explanation": "Keep '유미예요' as one block — it is not this lesson's focus."}], "options": [{"id": "o1", "text": "는", "mode": "turtle"}, {"id": "o2", "text": "저는", "mode": "rabbit"}, {"id": "o3", "text": "은", "mode": "turtle"}, {"id": "o4", "text": "저은", "mode": "rabbit"}, {"id": "o5", "text": "유미예요", "mode": "turtle"}, {"id": "o6", "text": "유미예요", "mode": "rabbit"}, {"id": "o7", "text": "저", "mode": "turtle"}]}}, {"step_type": "intro", "title": "Conversation", "instruction": "Take a break and listen. You know these words now.", "content": {"explanation": {"title": "Nice to meet you"}, "sentences": [{"korean": "민수: 안녕하세요. 제 이름은 민수예요.", "english": "Minsu: Hello. My name is Minsu.", "tts": true, "chunks": [{"display": "민수:", "tokens": [{"text": "민수", "meaning": "Minsu (speaker)"}]}, {"display": "안녕하세요.", "tokens": [{"text": "안녕하세요", "meaning": "Hello"}]}, {"display": "제", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "의", "meaning": "possessive marker"}]}, {"display": "이름은", "tokens": [{"text": "이름", "meaning": "name"}, {"text": "은", "meaning": "topic marker"}]}, {"display": "민수예요.", "tokens": [{"text": "민수", "meaning": "Minsu (name)"}, {"text": "예요", "meaning": "am/is/are (polite)"}]}]}, {"korean": "유미: 안녕하세요. 저는 유미예요. 반가워요.", "english": "Yumi: Hello. I am Yumi. Nice to meet you.", "tts": true, "chunks": [{"display": "유미:", "tokens": [{"text": "유미", "meaning": "Yumi (speaker)"}]}, {"display": "안녕하세요.", "tokens": [{"text": "안녕하세요", "meaning": "Hello"}]}, {"display": "저는", "tokens": [{"text": "저", "meaning": "I (polite)"}, {"text": "는", "meaning": "topic marker"}]}, {"display": "유미예요.", "tokens": [{"text": "유미", "meaning": "Yumi (name)"}, {"text": "예요", "meaning": "am/is/are (polite)"}]}, {"display": "반가워요.", "tokens": [{"text": "반가워요", "meaning": "nice to meet you"}]}]}, {"korean": "민수: 반가워요.", "eng